GimCorpus.put(394,0,[[4,3,"אין המתרגם רשאי לא לפחות ולא להוסיף ולא לשנות אלא אם כן היה המתורגמן אביו של חכם או רבו. א\"א דבר זה מקרה חדש היה והוא רב שעמד תורגמן לרבי שילא במסכת יומא ושנה והוסיף שהיה גדול ממנו:",1,0],[6,14,"המכשיל את העור. א\"א כגון המכה את בנו הגדול:",1,0],[6,14,"חכם ששמועתו רעה. א\"א ויש אחרים הרבה. חכם שהורה להתיר במים שאין להם סוף לינשא לכתחלה. וכן מי שעובר על נדרו כל בית דין שנזקק לו לשאלה בר שמתא הוא. ואיכא טובא:",2,0],[6,14,"מי שמנדה מי שאינו חייב בנדוי. א\"א דבר זה הוציא ממעשה דריש לקיש דהוה מנטר פרדיסא וכו' אמר ליה ההוא אדרבה ואמרו ליה שלו נדוי. ובחיי ראשי אין כאן פלפול כי הדברים שהוא מונה בית דין צריכין לנדותו ובכי האי גוונא לא היו בית דין נזקקין לנדות לר' שמעון בן לקיש אבל אותו שנידה והקפיד על כבודו נדויו נדוי:",3,0],[7,7,"בכמה מתירין הנידוי וכו'. א\"א זה אינו כן אלא כחשבון המנדין כך צורך המתירין וכחשיבותן. ואפשר כל זה כשירצו להתירו תוך זמן הנדר אבל כשישלים הזמן כל שלשה או יחיד מומחה מתירים לו. א\"נ כשנידהו יחיד ואפילו אינו מומחה על דבר עבירה וכשישלם לו הזמן מתירים לו כל שלשה או יחיד מומחה אבל נידוהו רבים צריכין רבים כמותם להתירו:",1,0],[7,11,"תלמיד חכם שנידה עצמו וכו'. א\"א זה אינו מחוור אם כן יהודה למה לא התיר לעצמו ועל כ\"ז קשה לי יעקב למה לא התירו:",1,0]]);
